Definition RWmE (C : rsc) (w : rsw) (s : as_St H) (errv : word) (ecs : list cell) (m : mem) : Prop :=
  let P := c_P C in let d := w_d w in let LB := ps_LBn d ++ c_LBin C in
     rw_cells bsegs m P (ParserCoreCells (ps_c d) (c_pad7 C) (c_pad2 C))
  /\ PutUw P (c_mb C) d m /\ HdrOwnA LB m (ps_h d)
  /\ rw_cells bsegs m (P + 240) [C1 (ps_rdi d)] /\ rw_cells bsegs m (P + 243) [CB 13 (c_j13 C)]
  /\ rw_cells bsegs m (P + 256) [CB 32 (c_j32a C)] /\ rw_cells bsegs m (P + 296) [CB 8 (c_j8a C)]
  /\ rw_cells bsegs m (P + 304) [CB 32 (c_j32b C)] /\ rw_cells bsegs m (P + 344) [CB 8 (c_j8b C)]
  /\ AHttpCat m (ps_g d) /\ (AFieldTabZero m \/ FT m) /\ AMiscVt48 m
  /\ AFlatBuf LB m (c_fb C) (w_FB w) (w_fds w) /\ rw_cells bsegs m (c_E C) ecs
  /\ rw_cells bsegs m (c_bs C) (BasicStreamCells (c_stb C))
  /\ AStateBlock LB m (c_stb C) (c_ioc C) (c_implb C)
       (mkST (mkSPC AVP_SPCI_STATE 1 1 1) 0 (w_Fs w) STREAM_EOF (w_nr w) (c_N C - zlength (w_sds w))) (w_sds w)
  /\ as_RHEAP H s LB m /\ rw_cells bsegs m (errno_addr (c_tp C)) [C4 errv] /\ as_rauxv_ok H m (c_B C) /\ mem_inv bsegs m
  /\ as_RFS H (c_LF C) m /\ ACONST m /\ stack0 m (c_lo C) (c_shi C) /\ athr_cells m
  /\ accessible m P PARSER_SIZE /\ accessible m (c_E C) 24 /\ shvis m (c_E C) (c_E C + 24)
  /\ accessible m (c_bs C) 32 /\ accessible m (c_fb C) 48
  /\ (1 <= c_N C -> shvis m (c_A C) (c_A C + c_N C)).

Lemma RWmE_of : forall C w s errv E m, RWm H C w s errv E m -> RWmE C w s errv (ErrCodeCells E) m.
Proof. intros C w s errv E m K. exact K. Qed.

